// ============ CONFIG RÉSONANCE — à remplir, identique dans les 7 workflows d'agents ============
return [{ json: {
  pipeline: "Prospection Résonance",          // nom exact du pipeline Pipedrive
  gemini_model: "gemini-flash-latest, gemini-flash-lite-latest", // un ou plusieurs modèles Google AI Studio, séparés par des virgules (répartition de la charge)
  pipedrive_base: "https://api.pipedrive.com/v1",
  gemini_base: "https://generativelanguage.googleapis.com/v1beta",
  gmail_base: "https://gmail.googleapis.com/gmail/v1/users/me",
  signataire: "Prénom Nom",                    // personne qui signe les emails
  emails_fondatrices: "",                      // adresses qui reçoivent alertes, arbitrage du lundi et export (séparées par des virgules ; vide = la boîte connectée)
  lien_rdv: "COLLER_ICI_LE_LIEN_DE_PRISE_DE_RENDEZ-VOUS",
  plafond_hebdo: 35,                           // premiers messages par semaine au maximum
  // Veille (agent 1)
  flux_rss: [ "COLLER_ICI_UNE_URL_DE_FLUX_RSS" ], // par exemple des flux Google Alertes
  label_veille: "veille",                      // libellé Gmail des newsletters et alertes à analyser
  fenetre_heures: 48,                          // âge maximal d'un article RSS
  max_articles: 25,
  // Bibliothèque de preuves validée par les fondatrices.
  // origine « À valider » = bloque le brouillon ; une phrase entre crochets est aussi bloquée par le contrôle automatique.
  preuves: [
    { id: "vins", segment: "Vins & Spiritueux", origine: "Projet Anna & Louise", phrase: "[Phrase de preuve validée : projet réalisé pour une maison de ce segment]" },
    { id: "beaute", segment: "Beauté & Parfumerie", origine: "Projet Anna & Louise", phrase: "[Phrase de preuve validée : projet réalisé pour une maison de ce segment]" },
    { id: "joaillerie", segment: "Joaillerie & Horlogerie", origine: "Expérience des fondatrices (autre structure)", phrase: "[Phrase de preuve validée : expérience antérieure des fondatrices]" },
    { id: "mode", segment: "Mode & Maroquinerie", origine: "À valider", phrase: "[Phrase de preuve en attente de validation]" }
  ],
  // Emails des fondatrices ou de l'agence ayant obtenu une réponse (modèles de style de l'agent 4)
  exemples_valides: []
}}];

// Compare les champs existants à la liste du kit et ne garde que ceux qui manquent
const n = s => String(s || '').trim();
const LONG = ["Extrait source", "Résumé du signal", "Fait vérifié", "Hypothèse", "Détail du score", "Motif du score", "Texte du dernier message"];
const DEAL = ["Type de signal", "URL source", "Date de publication", "Extrait source", "Résumé du signal", "Catégorie", "Taille budget", "Porte d'entrée", "Adéquation expertises", "Fait vérifié", "Hypothèse", "Preuve A&L", "Score Résonance", "Détail du score", "Motif du score", "Niveau", "Angle", "Prochaine action", "Activer", "Discrétion IA", "Brouillon généré", "Texte du dernier message", "Date premier envoi", "Nb relances", "Tâche LinkedIn", "Reprise le", "Date de réactivation", "Motif de refus", "Fin de conservation"];
const PERS = ["Civilité", "Poste", "Niveau de décision", "Opposition", "Provenance coordonnées", "Fiabilité email"];
const deja = arr => new Set((arr || []).map(f => n(f.name)));
const d = deja($('Champs affaires').first().json.data), p = deja($('Champs personnes').first().json.data);
const out = [];
for (const name of DEAL) if (!d.has(name)) out.push({ json: { endpoint: 'dealFields', objet: 'Affaire', name, field_type: LONG.includes(name) ? 'text' : 'varchar' } });
for (const name of PERS) if (!p.has(name)) out.push({ json: { endpoint: 'personFields', objet: 'Personne', name, field_type: 'varchar' } });
return out.length ? out : [{ json: { rien: true } }];

// Bilan : champs créés + contrôle des étapes du pipeline
const cfg = $('CONFIG').first().json;
const n = s => String(s || '').trim();
const STAGES = ["À rechercher", "À qualifier", "Prêt à contacter", "Contacté", "À relancer", "Conversation ouverte", "Rendez-vous", "En pause"];
const crees = $('Champs manquants').all().filter(i => !i.json.rien).map(i => i.json.objet + ' · ' + i.json.name);
const et = ($('Étapes').first().json.data || []).filter(s => n(s.pipeline_name) === cfg.pipeline).map(s => n(s.name));
const manquantes = STAGES.filter(s => !et.includes(s));
return [{ json: {
  champs_crees: crees.length ? crees : ['Aucun : tous les champs existaient déjà'],
  pipeline: et.length ? 'trouvé' : 'INTROUVABLE : créez le pipeline « ' + cfg.pipeline + ' »',
  etapes_a_corriger: manquantes.length ? manquantes.map(s => 'Étape manquante ou mal écrite : « ' + s + ' »') : ['Les 8 étapes sont correctes']
} }];
